function toast(message,undoFn){clearTimeout(toastTimer);undo=undoFn||null;$('#toast').innerHTML=escape(message)+(undo?' <button data-action="undo">Undo</button>':'');$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,7000)}
