 if(state.settings.layout==='list'){el.innerHTML=`<div class="list-view">${tasks.map((t,i)=>taskMarkup(t,i,190)).join('')}</div>`;return}
 const width=el.getBoundingClientRect().width;const columns=Math.min(tasks.length,width>680?3:width>320?2:1),buckets=Array.from({length:columns},()=>[]),heights=Array(columns).fill(0),ratios=columns===3?[.94,1.12,.94]:columns===2?[1,1]:[1];
