function monthCells(d,mini=false){const dt=dateOf(d),y=dt.getFullYear(),m=dt.getMonth(),first=new Date(y,m,1),start=new Date(y,m,1-first.getDay());return Array.from({length:42},(_,i)=>{const day=new Date(start);day.setDate(start.getDate()+i);const key=dateKey(day),items=state.tasks.filter(t=>t.date===key);if(mini)return `<span class="${key===today?'today':''}" style="opacity:${day.getMonth()===m?1:.25}">${day.getDate()}</span>`;return `<button class="day-cell ${day.getMonth()!==m?'outside':''} ${key===today?'today':''}" data-action="pick-date" data-date="${key}" data-hover-date="${key}" aria-label="${escape(fmt(key,{month:'long',day:'numeric',year:'numeric'}))}, ${items.length} appointments" style="animation-delay:${Math.min(i*10,250)}ms"><span class="date-number">${day.getDate()}</span><span class="date-dots">${items.slice(0,3).map(()=>'<i></i>').join('')}</span></button>`}).join('')}
